// Production handler: Introduction to JavaScript
export async function executeAutomation(eventData) {
  const endpoint = process.env.SERVICE_WEBHOOK_URL;

  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Idempotency-Key': eventData.id || crypto.randomUUID()
    },
    body: JSON.stringify({
      event: 'introduction_to_javascript',
      timestamp: new Date().toISOString(),
      data: eventData
    })
  });

  if (!response.ok) {
    throw new Error(`Execution error HTTP ${response.status}: ${await response.text()}`);
  }
  return await response.json();
}

